typedef struct tagAttribute
{
        i32 a;
} Attribute, *PAttribute;

typedef struct tagMutex
{
        dwl_bool locked;
        Attribute attrib;
} Mutex, *PMutex;

typedef struct tagEvent
{
        dwl_bool singaled;
        Attribute attrib;
} Event, *PEvent;

typedef struct tagSemaphore
{
        i32 val;
} Semaphore, *PSemaphore;

#define sem_t Semaphore

#define __u8 u8
#define __i8 i8
#define __u32 u32
