  u32 vp8_max_dec_pic_height;
  u32 vp7_max_dec_pic_width;
  u32 vp7_max_dec_pic_height;
  u32 vp6_max_dec_pic_width;
  u32 vp6_max_dec_pic_height;
  u32 avs_max_dec_pic_width;
  u32 avs_max_dec_pic_height;
