  /*low_cost_scale: Bicubic/Bilinear/Nearest/Area */
  u32 scale_cost_support[6];
  /*scale: Area*/
  u32 only_area_scale_alg_support[6];
  /*crop_step_rshift: 0:support odd/even crop, 1:support even crop*/
